// The numbers come from the backend twin app/api/dimev3/reports/loans/loans/list/LoansLoansSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import LoansLoansActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const LoansLoansSchema = {
  entity: 'device_loans_performance',
  label: 'Loans Performance',
  description: '',
  apiBase: apiRoutes.loansloans?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: LoansLoansActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'day', label: 'Day' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'loans', label: 'Loans Issued', from: 'loans' },
    { key: 'principal', label: 'Principal Lent', from: 'loans.principal', type: 'money' },
    { key: 'interest', label: 'Interest Charged', from: 'loans.interest', type: 'money' },
    { key: 'deposits', label: 'Deposits Received', from: 'loans.deposit', type: 'money' },
    { key: 'expected', label: 'Expected Repayment', calc: 'principal + interest', type: 'money' },
    { key: 'paid', label: 'Total Repaid', from: 'loans.total_paid', type: 'money' },
    { key: 'balance', label: 'Outstanding Balance', from: 'loans.balance', type: 'money' },
    { key: 'avg_loan', label: 'Average Loan Size', calc: 'principal / loans', type: 'money' },
    { key: 'chg', label: 'Lending vs Previous Period', calc: 'change(principal)' },
  ],

  remarks: [
    { if: 'loans == 0', tone: 'watch', title: 'No loans', say: 'No loans were issued in {label}.' },
    { if: 'balance > principal', tone: 'bad', title: 'High outstanding balance', say: 'Outstanding balance of {balance} exceeds principal lent of {principal}.' },
    { if: 'chg !== null && chg <= -20', tone: 'watch', title: 'Lending declined', say: 'Principal lent fell by {abs(chg)}% compared with {prev_label}.' },
    { if: 'true', tone: 'neutral', title: 'Loan performance', say: '{loans} loans issued, {paid} repaid and {balance} outstanding.' },
  ],

  headline: '{label}: {loans} loans issued, {principal} lent, {balance} outstanding.',

  // coming periods the report page adds after the history (see forecast.js)
  forecast: [{ key: 'loans', next: 10, method: 'auto', integer: true }, { key: 'principal', next: 10, method: 'auto', integer: false }],
};
